 // initRanNoTests classifies only recognized reports; positive evidence wins.
 func initRanNoTests(output string) bool {
-	return initNoTestsRE.MatchString(output) && !initPositiveTestsRE.MatchString(output)
+	return initNoTestsRE.MatchString(output) && !initPositiveTestsRE.MatchString(output) && !initGoRanTests(output)
 }

+// initGoRanTests reports a Go package line that ran tests: every ok line except one that
+// ends in [no tests to run].
+func initGoRanTests(output string) bool {
+	for _, line := range initGoOkLineRE.FindAllString(output, -1) {
+		if !initGoNoTestsToRunRE.MatchString(line) {
+			return true
+		}
+	}
+	return false
+}
